def check_wash_f04_receiver_bundle(root,d):
    package = root / 'outputs/IMPLEMENTER_SUPPLEMENTS/F04-RECEIVER-APPROVED-PARAMETERS-V1'
    manifest_path = package / 'MANIFEST.json'
    raw = manifest_path.read_bytes()
    manifest = json.loads(raw)
    expected_manifest_sha = '161147c7959083738f5426b2280457454b08b73ee58a075322c33880cecc818b'
    expected_parent_sha = 'c7cddb7d5ac073c0f410fe44be9a431cfbb21c3df469d8b43c32a4297298674a'
    expected_files = {
        'parameters/component-parameter-mathematical-v1.json': (1077, '5d0fec6f62a33eeef5c64016760fcbe94a1872a564b6d0e03f959c95c37eb0f5'),
        'parameters/window-q15.json': (2704, 'a12f9cbf91f1cf540c2eae77e4d236970defa70409f00ddf62ba87bfeafbb130'),
        'parameters/qmf-receiver-functional-v1.json': (20325, '30e63cc110b63dd88118ad37f02750a39167bd01279a3b40853afdf3151b552c'),
        'parameters/qmf-mathematical-fft-v1.json': (6983, 'e8d3fb1514a5ffd857740222eacc8995208a29c3447e48c1b63083af368c0431'),
        'parameters/descriptor-mathematical.json': (4861, 'a493fbdaf2dab30e940cae9976ed3305f3af083e5614ab0cbd6889c71a02b197'),
    }
    actual_files = {}
    for item in manifest.get('files', []):
        path = item.get('file')
        if not isinstance(path, str) or path in actual_files:
            raise BoundaryError('duplicate or malformed F04 receiver bundle path')
        actual_files[path] = (item.get('bytes'), item.get('sha256'))
    ck(hashlib.sha256(raw).hexdigest() == expected_manifest_sha
       and manifest.get('package_id') == 'F04-RECEIVER-APPROVED-PARAMETERS-V1'
       and manifest.get('approved_package_manifest_sha256') == expected_parent_sha
       and actual_files == expected_files,
       'Wash F04 receiver subset manifest identity and exact parent binding')
    for relative, (size, sha) in expected_files.items():
        payload = (package / relative).read_bytes()
        ck(len(payload) == size and hashlib.sha256(payload).hexdigest() == sha,
           'Wash F04 receiver payload identity ' + relative)

    entry = next(item for item in d['functional_entries'] if item['functional_id'] == 'F04R')
    provider_slice = next(item for item in entry['direct_slices'] if item['slice_id'] == 'selected-spatial-audio-provider-bundle')
    implementation_inventory = [
        {'path': name, 'bytes': (root / name).stat().st_size, 'sha256': hashlib.sha256((root / name).read_bytes()).hexdigest()}
        for name in provider_slice['implementation_files']
    ]
    test_inventory = [
        {'path': name, 'bytes': (root / name).stat().st_size, 'sha256': hashlib.sha256((root / name).read_bytes()).hexdigest()}
        for name in provider_slice['test_modules']
    ]
    validator = (root / 'crates/jocforge-domain/src/spatial/window_q15_provider.rs').read_text(encoding='utf-8')
    io_loader = (root / 'crates/jocforge-io/src/provider/spatial_audio.rs').read_text(encoding='utf-8')
    cli_loader = (root / 'crates/jocforge-cli/src/selected_spatial_callback_providers.rs').read_text(encoding='utf-8')
    application = (root / 'crates/jocforge-application/src/spatial_callback.rs').read_text(encoding='utf-8')
    ck(provider_slice['implementation_status'] == 'LOCALLY_VERIFIED_WASH_F04_RECEIVER_SUBSET_AND_MAIN_COMPOSITION__G2_RECEIVER_NOT_RUN'
       and provider_slice['parameters']['subset_manifest_sha256'] == expected_manifest_sha
       and provider_slice['parameters']['approved_parent_manifest_sha256'] == expected_parent_sha
       and provider_slice['implementation_inventory'] == implementation_inventory
       and provider_slice['test_inventory'] == test_inventory
       and 'RECEIVER_PARAMETER_BUNDLE_SHA256' in validator
       and 'load_selected_spatial_audio_provider_bundle' in io_loader
       and 'load_selected_main_spatial_callback_providers' in cli_loader
       and 'ReceiverProvidersRequired' in application,
       'F04 receiver subset is wired through validated IO and MAIN provider gates without claiming g2 execution')


